const socialLinks=[['Instagram','https://www.instagram.com/packtuning/','instagram','◎'],['Facebook','https://www.facebook.com/groups/1561529331198175','facebook','f'],['LinkedIn','https://www.linkedin.com/groups/10072044/','linkedin','in'],['ВКонтакте','https://vk.ru/club79622771','vk','VK']];
const socials=document.createElement('div');socials.className='start-socials';socials.setAttribute('role','group');socials.setAttribute('aria-label','PackTuning — социальные сети');
socialLinks.forEach(([name,url,brand,glyph])=>{const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.className='social-link '+brand;a.title=name+' · PackTuning';a.setAttribute('aria-label',name+' PackTuning');a.textContent=glyph;socials.append(a);});document.querySelector('.language').before(socials);
function card(p,lang,included){const localized=lang==='en';const title=localized?p.en:p.ru;const href=new URL(localized&&p.urlEn?p.urlEn:p.url,location.origin);href.searchParams.set('lang',lang);const icon=p.icon.startsWith('/')?p.icon:'/assets/icons/'+p.icon+'.png';const banner=p.bannerRu?(localized?p.bannerEn:p.bannerRu):included?p.banner+(localized?'_en':'')+'.png':(p.bundle||p.hero)?'/'+p.banner+'-'+lang+'.png':'/'+p.banner+(localized?'_en':'')+'.png';return `<article class="catalog-card"><a class="catalog-cover" href="${href.pathname+href.search+href.hash}"><img src="${banner}" alt="${title}" loading="lazy"></a><a class="catalog-card-head" href="${href.pathname+href.search+href.hash}"><img src="${icon}" width="52" height="52" alt=""><div><h3>${title}</h3><span class="catalog-badge">${included?(localized?p.editionEn:p.edition):'Windows · B2B'}</span></div></a><p>${localized?p.descriptionEn:p.description}</p>${p.price?'<strong class="catalog-price">'+p.price+'</strong>':''}<div class="catalog-card-actions"><a class="btn" href="${href.pathname+href.search+href.hash}">${localized?'Explore →':'Страница →'}</a>${included?'<a class="btn primary" href="#demo">'+(localized?'Try demo':'Демоверсия')+'</a>':''}</div></article>`;}

const params=new URLSearchParams(location.search);
let lang=params.get('lang')==='en'?'en':'ru';
function setLanguage(value){
 lang=value;const en=lang==='en';
 document.documentElement.lang=lang;document.documentElement.dataset.lang=lang;
 document.querySelectorAll('[data-ru][data-en]').forEach(el=>el.textContent=el.dataset[lang]);
 document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));
 document.querySelector('#hero').src='/Standards/assets/hero-'+lang+'.png';
 document.querySelector('#hero').alt=en?'GOST Standards Guide — GOST Bundle banner':'Справочник ГОСТов — баннер комплекта ГОСТы';
 document.title=en?'GOST Bundle — Standards Guide and Load Calculator | PackTuning':'Комплект «ГОСТы» — справочник и расчёт нагрузки | PackTuning';
 const description=en?'GOST Standards Guide and GOST 9142-2014 Load Calculator. Two integrated full versions, perpetual licenses for one workstation. €159.':'Справочник ГОСТов и расчёт нагрузки по ГОСТ 9142-2014. Две полные версии с взаимной интеграцией. Бессрочные лицензии на одно рабочее место — 15 900 ₽.';
 document.querySelector('meta[name="description"]').content=description;
 document.querySelector('meta[property="og:title"]').content=document.title;
 document.querySelector('meta[property="og:description"]').content=description;
 document.querySelector('meta[property="og:image"]').content='https://governorv.github.io/Standards/assets/hero-'+lang+'.png';
 const schema=document.querySelector('#bundle-schema');const data=JSON.parse(schema.textContent);
 data.offers.price=en?'159':'15900';data.offers.priceCurrency=en?'EUR':'RUB';schema.textContent=JSON.stringify(data);
 document.querySelector('#suite-cards').innerHTML='<div class="catalog-cards">'+suite.map(p=>card(p,lang,true)).join('')+'</div>';
 document.querySelector('#related-cards').innerHTML=related.map(p=>card(p,lang,false)).join('');
 suite.forEach(p=>document.querySelector('[data-demo="'+p.id+'"]').href=en?p.demoEn:p.demoRu);
 document.querySelectorAll('a').forEach(a=>{const u=new URL(a.href,location.href);if(u.origin===location.origin&&!a.getAttribute('href').startsWith('#')&&!/\.(png|jpg|jpeg|webp|zip)$/.test(u.pathname)){u.searchParams.set('lang',lang);a.href=u.pathname+u.search+u.hash;}});
 const current=new URL(location.href);current.searchParams.set('lang',lang);history.replaceState(null,'',current);
}
document.querySelectorAll('[data-lang]').forEach(el=>el.addEventListener('click',()=>setLanguage(el.dataset.lang)));
setLanguage(lang);
